import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { ChevronLeft, ChevronRight, Mail, Phone, MessageCircle } from 'lucide-react';
import img1 from '../assets/img1.png';
import img2 from '../assets/img2.png';
import img3 from '../assets/img3.png';
import img4 from '../assets/img4.png';
import img5 from '../assets/img5.png';

const HomePage = () => {
  const [currentMainSlide, setCurrentMainSlide] = useState(0);
  const [currentSecondarySlide, setCurrentSecondarySlide] = useState(0);
  
  const mainImages = [img1, img2, img3];
  const secondaryImages = [img4, img5];
  
  // Auto-slide effects
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentMainSlide((prev) => (prev + 1) % mainImages.length);
    }, 100000);
    return () => clearInterval(interval);
  }, [mainImages.length]);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentSecondarySlide((prev) => (prev + 1) % secondaryImages.length);
    }, 10500);
    return () => clearInterval(interval);
  }, [secondaryImages.length]);

  const nextMainSlide = () => {
    setCurrentMainSlide((prev) => (prev + 1) % mainImages.length);
  };

  const prevMainSlide = () => {
    setCurrentMainSlide((prev) => (prev - 1 + mainImages.length) % mainImages.length);
  };

  return (
    <div className="min-h-screen flex flex-col bg-gray-100">
      {/* Banner naranja */}
      <div className="bg-[#FF6B00] text-white h-64 py-12 md:py-20 px-6 text-center w-full">
        <h1 className="text-4xl md:text-5xl font-bold mb-2">VIDEOJUEGOS</h1>
        <h2 className="text-2xl md:text-3xl font-light mb-2">H A B A N A</h2>
        <Link 
          to="/shop" 
          className="inline-block bg-black text-white px-8 py-3 rounded-lg font-medium text-lg hover:bg-gray-800 transition-colors duration-300"
        >
          Empiece su compra
        </Link>
      </div>

      {/* Separador negro */}
      <div className="bg-black h-12 w-full"></div>

      {/* Carrusel principal */}
      <div className="relative h-64 md:h-80 bg-[#FF6B00] w-full overflow-hidden">
        {/* Imagen del carrusel - ocupa todo el espacio */}
        <img 
          src={mainImages[currentMainSlide]} 
          alt={`Slide ${currentMainSlide + 1}`}
          className="absolute inset-0 w-full h-full object-cover"
          style={{ objectPosition: 'center' }}
        />

        {/* Controles */}
        <button 
          onClick={prevMainSlide}
          className="absolute left-4 top-1/2 transform -translate-y-1/2 text-white z-30 hover:text-gray-200 transition-colors bg-black bg-opacity-30 rounded-full p-2"
        >
          <ChevronLeft size={32} />
        </button>
        <button 
          onClick={nextMainSlide}
          className="absolute right-4 top-1/2 transform -translate-y-1/2 text-white z-30 hover:text-gray-200 transition-colors bg-black bg-opacity-30 rounded-full p-2"
        >
          <ChevronRight size={32} />
        </button>
      </div>

      {/* Panel de contenido */}
      <div className="flex-grow px-4 md:px-8 py-8">
        <div className="bg-white rounded-lg shadow-md p-6 max-w-6xl mx-auto">
          <div className="flex flex-col md:flex-row gap-6">
            {/* Texto de bienvenida */}
            <div className="flex-1">
              <h2 className="text-2xl md:text-3xl font-bold text-gray-800 mb-3">Bienvenidos</h2>
              <p className="text-[#FF6B00] font-medium mb-3">sum dolor sit amet</p>
              <p className="text-gray-600 mb-3">
                djansfdudsufkjdsbffjdsjfds nfjdsnfjdlndsjfnkdsjfnkdsj
                fndsifnfjdsnfjdankjfdsnk fjndsktjdskvtjndsktjndsktfd
                sjfndskjfnkdsjnfjdsnfndsn fjdsnfjndsfijdsfnjdsfnksjdf
              </p>
              <p className="text-gray-600">
                ndsfjndsfnjdsnfjdsnjdsnjfn kdsj ipsum dolor sit amet,
                consectetur adipiscing
              </p>
            </div>

            {/* Carrusel secundario compacto */}
            <div className="w-full md:w-64 bg-[#FF6B00] rounded-lg overflow-hidden relative">
              <img 
                src={secondaryImages[currentSecondarySlide]} 
                alt="Mensajería"
                className="w-full h-full object-cover"
                style={{ minHeight: '200px' }}
              />
              
              <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 flex justify-center space-x-1">
                {secondaryImages.map((_, index) => (
                  <div
                    key={index}
                    className={`w-2 h-2 rounded-full ${
                      index === currentSecondarySlide ? 'bg-white' : 'bg-white bg-opacity-50'
                    }`}
                  />
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Pie de página negro */}
      <footer className="bg-black text-white py-6 w-full mt-auto">
        <div className="container mx-auto px-4">
          <div className="flex justify-center space-x-8 md:space-x-12">
            <div className="flex flex-col items-center">
              <Mail size={24} className="mb-1" />
              <span className="text-xs md:text-sm">Email</span>
            </div>
            <div className="flex flex-col items-center">
              <Phone size={24} className="mb-1" />
              <span className="text-xs md:text-sm">Teléfono</span>
            </div>
            <div className="flex flex-col items-center">
              <MessageCircle size={24} className="mb-1" />
              <span className="text-xs md:text-sm">WhatsApp</span>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default HomePage;