import React, { createContext, useContext, useState, useEffect } from 'react';

const CartContext = createContext();

export const CartProvider = ({ children }) => {
  const [cartItems, setCartItems] = useState([]);

  // Cargar carrito desde localStorage al iniciar
  useEffect(() => {
    const savedCart = localStorage.getItem('cart');
    if (savedCart) {
      try {
        setCartItems(JSON.parse(savedCart));
      } catch (error) {
        console.error('Error parsing cart data:', error);
        localStorage.removeItem('cart');
      }
    }
  }, []);

  // Guardar carrito en localStorage cuando cambia
  useEffect(() => {
    localStorage.setItem('cart', JSON.stringify(cartItems));
  }, [cartItems]);

  // Vaciar carrito completamente
  const clearCart = () => {
    setCartItems([]);
    localStorage.removeItem('cart');
  };

  // Añadir producto al carrito
  const addToCart = (product) => {
    setCartItems(prevItems => {
      // Si es una variación
      if (product.variacion) {
        const existingItem = prevItems.find(item => 
          item.id === product.id && 
          item.isVariation && 
          item.variacion?.id === product.variacion.id
        );
        
        if (existingItem) {
          return prevItems.map(item =>
            item.id === product.id && 
            item.isVariation && 
            item.variacion?.id === product.variacion.id
              ? { ...item, quantity: item.quantity + 1 }
              : item
          );
        }
        
        return [
          ...prevItems,
          {
            ...product,
            quantity: 1,
            isVariation: true,
            price: product.variacion.precio_post_descuento || product.variacion.precio,
            image: product.variacion.imagen || product.imagenes?.[0]?.imagen || '',
            color: product.variacion.color,
            model: product.variacion.modelo,
            warranty: product.variacion.garantia_tiempo,
            gift: product.variacion.regalo_nombre
          }
        ];
      }
      
      // Si es un producto normal
      const existingItem = prevItems.find(item => 
        item.id === product.id && !item.isVariation
      );
      
      if (existingItem) {
        return prevItems.map(item =>
          item.id === product.id && !item.isVariation
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }
      
      return [
        ...prevItems,
        {
          ...product,
          quantity: 1,
          isVariation: false,
          price: product.precio_post_descuento || product.precio,
          image: product.imagenes?.[0]?.imagen || '',
          warranty: product.garantia_tiempo,
          gift: product.regalo_nombre
        }
      ];
    });
  };

  // Eliminar producto del carrito
  const removeFromCart = (productId, isVariation, variationId) => {
    setCartItems(prevItems => 
      prevItems.filter(item => 
        isVariation 
          ? !(item.id === productId && item.isVariation && item.variacion?.id === variationId)
          : !(item.id === productId && !item.isVariation)
      )
    );
  };

  // Actualizar cantidad de un producto
  const updateQuantity = (productId, isVariation, variationId, newQuantity) => {
    if (newQuantity < 1) {
      removeFromCart(productId, isVariation, variationId);
      return;
    }
    
    setCartItems(prevItems =>
      prevItems.map(item =>
        isVariation
          ? item.id === productId && item.isVariation && item.variacion?.id === variationId
            ? { ...item, quantity: newQuantity }
            : item
          : item.id === productId && !item.isVariation
            ? { ...item, quantity: newQuantity }
            : item
      )
    );
  };

  // Calcular cantidad total de items
  const totalItems = cartItems.reduce((sum, item) => sum + item.quantity, 0);
  
  // Calcular total del carrito
  const calculateTotal = () => {
    return cartItems.reduce(
      (sum, item) => sum + (parseFloat(item.price) || 0) * item.quantity,
      0
    );
  };

  return (
    <CartContext.Provider 
      value={{ 
        cartItems, 
        addToCart, 
        removeFromCart, 
        updateQuantity,
        totalItems,
        calculateTotal,
        clearCart
      }}
    >
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => {
  const context = useContext(CartContext);
  if (!context) {
    throw new Error('useCart must be used within a CartProvider');
  }
  return context;
};